findings.codeql_raw_query:
/**
 * @name wrapt eval/exec usage path from remote sources
 * @description Trace potential data flow from remote sources to eval/exec/compile in wrapt decorators
 * @kind path-problem
 * @problem.severity error
 * @id py/wrapt-remote-to-eval
 * @tags security
 *       external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module WraptEvalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(CodeExecution ce |
      sink = ce.getCode() and
      ce.getLocation().getFile().getRelativePath().matches("src/wrapt/%")
    )
  }
}

module WraptEvalFlow = TaintTracking::Global<WraptEvalConfig>;
import WraptEvalFlow::PathGraph

from WraptEvalFlow::PathNode source, WraptEvalFlow::PathNode sink
where WraptEvalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled data reaches code execution in wrapt: $@.", source.getNode(), "user input"
